/// Effective memory settings: `[memory]` from `leviathan.toml`, then flags.
#[derive(Debug, Clone)]
pub struct Settings {
    pub namespace: String,
    pub read: Vec<String>,
    pub budget: usize,
    pub briefing_budget: usize,
    pub max_chars: usize,
    pub pin: Vec<String>,
    half_life: BTreeMap<Kind, f64>,
}

impl Settings {
    pub fn from_config(cfg: &MemoryConfig) -> Self {
        let half_life = Kind::ALL
            .into_iter()
            .map(|k| {
                let days = cfg
                    .half_life
                    .iter()
                    .find(|(name, _)| Kind::parse(name) == Some(k))
                    .map_or(k.default_half_life(), |(_, d)| *d);
                (k, days)
            })
            .collect();
        let namespace = cfg.namespace.trim().to_lowercase();
        let read = if cfg.read.is_empty() {
            vec![namespace.clone()]
        } else {
            cfg.read.iter().map(|n| n.trim().to_lowercase()).collect()
        };
        Self {
            namespace,
            read,
            budget: cfg.budget,
            briefing_budget: cfg.briefing_budget,
            max_chars: cfg.max_chars,
            pin: cfg.pin.clone(),
            half_life,
        }
    }

    pub fn half_life(&self, kind: Kind) -> f64 {
        self.half_life.get(&kind).copied().unwrap_or(0.0)
    }
}

impl Default for Settings {
    fn default() -> Self {
        Self::from_config(&MemoryConfig::default())
    }
}

/// `~/.leviathan/memory.db`, or under `LEVIATHAN_HOME` when set.
pub fn default_path() -> PathBuf {
    if let Some(home) = std::env::var_os("LEVIATHAN_HOME").filter(|v| !v.is_empty()) {
        return PathBuf::from(home).join("memory.db");
    }
    match home_dir() {
        Some(home) => home.join(".leviathan").join("memory.db"),
        None => PathBuf::from("leviathan-memory.db"),

    /// Namespaces recall reads by default [default: just `namespace`].
    pub read: Vec<String>,
    /// Token budget for one recall.
    pub budget: usize,
    /// Token budget for the session-start briefing.
    pub briefing_budget: usize,
    /// Character cap for one memory.
    pub max_chars: usize,
    /// Recency half-life in days per kind; 0 means no decay.
    pub half_life: std::collections::BTreeMap<String, f64>,
    /// Subjects whose memories lead every briefing.
    pub pin: Vec<String>,
}

impl Default for MemoryConfig {
    fn default() -> Self {
        Self {
            path: None,
            namespace: "default".into(),
            read: Vec::new(),
            budget: 800,
            briefing_budget: 600,
            max_chars: 400,
            half_life: Default::default(),
            pin: Vec::new(),
        }
    }
}

